static string Signature(){string s="";foreach(object n in List("journeyRooms"))s+=Get(n,"cell")+":"+Get(n,"kind")+":"+Get(n,"layout")+";";return s;}
static void Graphs(){var sig=new HashSet<string>();bool connected=true,cardinal=true,branch=false;for(int seed=1;seed<=50;seed++){Call("BuildSpatialGraph",new System.Random(seed));IList rooms=List("journeyRooms");var seen=new HashSet<int>();var q=new Queue<int>();q.Enqueue(0);while(q.Count>0){int id=q.Dequeue();if(!seen.Add(id))continue;object n=rooms[id];foreach(int link in (List<int>)Get(n,"links")){q.Enqueue(link);Vector2Int a=(Vector2Int)Get(n,"cell"),b=(Vector2Int)Get(rooms[link],"cell");cardinal&=Mathf.Abs(a.x-b.x)+Mathf.Abs(a.y-b.y)==1&&((List<int>)Get(rooms[link],"links")).Contains(id);}int stairs=I(n,"stairsTo");if(stairs>=0)q.Enqueue(stairs);branch|=((List<int>)Get(n,"links")).Count>=3;}connected&=seen.Count==39;sig.Add(Signature());}Check(connected&&cardinal,"50 seeds connect all 39 rooms through cardinal links and stairs");Check(branch&&sig.Count==50,"Seeds vary spatial layouts with branching routes");Call("BuildSpatialGraph",new System.Random(1729));string a1=Signature();Call("BuildSpatialGraph",new System.Random(1729));Check(a1==Signature(),"Same seed reproduces spatial graph");}
static bool Reach(Vector2 start,Vector2 goal){const float step=.22f;var seen=new HashSet<Vector2Int>();var q=new Queue<Vector2Int>();Vector2Int root=Vector2Int.RoundToInt(start/step);q.Enqueue(root);int guard=0;while(q.Count>0&&guard++<30000){Vector2Int cell=q.Dequeue();if(!seen.Add(cell))continue;Vector2 at=(Vector2)cell*step;if(Vector2.Distance(at,goal)<.35f)return true;foreach(Vector2Int d in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.right,Vector2Int.left}){Vector2Int next=cell+d;Vector2 point=(Vector2)next*step;if(!seen.Contains(next)&&(bool)Call("CanStandInExploration",point,.3f)&&!(bool)Call("Blocked",point,.3f))q.Enqueue(next);}}return false;}
static void Navigation(){bool reachable=true,spawn=true;for(int id=0;id<39;id++){Enter(id);object n=List("journeyRooms")[id];foreach(object pending in List("pendingSpawns")){Vector2 at=(Vector2)Get(pending,"at");spawn&=!(bool)Call("Blocked",at,.38f)&&!(bool)Call("ProjectilePathBlocked",at,at,.3f);}Set(n,"cleared",true);Call("UpdateExplorationDoors");Vector2 start=(Vector2)Get(p,"position");foreach(int link in (List<int>)Get(n,"links")){int dir=(int)Call("NeighborDirection",n,List("journeyRooms")[link]);Vector2 end=(Vector2)Call("DoorPoint",dir,1.15f);bool r=Reach(start,end);if(!r)Debug.Log("Unreachable door room "+id+" dir "+dir);reachable&=r;}if(Get(p,"stairs")!=null)reachable&=Reach(start,(Vector2)Get(p,"stairPosition"));if(id==0||id==14||id==30)Capture("room-"+id);}
Check(reachable,"All 39 layouts have walking paths to every door and stair");Check(spawn,"Queued waves spawn outside movement and projectile cover");Fresh();int target=((List<int>)Get(List("journeyRooms")[0],"links"))[0];object from=List("journeyRooms")[0];int d1=(int)Call("NeighborDirection",from,List("journeyRooms")[target]);TimeAt(20);Set(p,"position",Call("DoorPoint",d1,1.2f));Call("TryAutomaticExit");Check(I(p,"transitionTarget")==target,"Walking through open corridor starts neighbor transition");float oldShield=F(p,"shield"),oldClock=F(p,"clock");for(int i=0;i<7;i++)Call("TickDoorTransition",.05f);Check(I(p,"currentRoom")==target&&Mathf.Abs(F(p,"clock")-oldClock)<.001f&&F(p,"shield")==oldShield,"Door transition preserves shield and simulation time");Check(Vector2.Distance((Vector2)Get(p,"position"),(Vector2)Call("DoorPoint",d1^1,-.85f))<.01f,"Arrival uses opposite door");Check(!(bool)Get(List("journeyRooms")[target],"cleared")&&!(bool)Call("CanStandInExploration",Call("DoorPoint",d1^1,1f),.3f),"Combat seals passage until waves are cleared");}
static void Defenses(){TimeAt(10);Call("TakeJourneyDamage",2f,EnumValue("Element","Physical"));Check(F(p,"shield")==2&&F(p,"health")==6,"Shield absorbs damage before life");Call("TakeJourneyDamage",2f,EnumValue("Element","Physical"));Check(F(p,"shield")==2,"Damage invulnerability prevents immediate repeat hits");TimeAt(12);Call("TakeJourneyDamage",3f,EnumValue("Element","Physical"));Check(F(p,"shield")==0&&F(p,"health")==5,"Shield overflow subtracts remaining damage from life");TimeAt(16.9f);Call("TickPlayerDefenses",.1f);Check(F(p,"shield")==0,"Shield waits five seconds after last damage");TimeAt(17.1f);Call("TickPlayerDefenses",1f);Check(Mathf.Abs(F(p,"shield")-1)<.001f,"Shield recharges one point per second");float s=F(p,"shield");Enter(1);Check(F(p,"shield")==s&&F(p,"lastDamageAt")==12,"Changing rooms preserves shield and hit timestamp");}
static void Skills(){TimeAt(10);Call("CastJourneyOrb");Check(List("shots").Count==0&&!((bool)Get(p,"orbLearned")),"Orb is locked on a fresh run");Set(p,"clearedCombatRooms",3);Call("CheckPendingLesson");Check(I(p,"pendingLesson")==1&&Get(p,"lessonAltar")!=null,"Third combat clear creates learning altar");Call("LearnPendingLesson");Quiet();Set(p,"position",new Vector2(0,-2));Set(p,"facing",Vector2.right);Set(p,"energy",100f);TimeAt(20);Call("CastJourneyOrb");Check(List("shots").Count==1&&F(p,"energy")==80,"Learned orb creates exactly one projectile for twenty mana");object shot=List("shots")[0];Check(F(shot,"damage")==24&&F(shot,"life")==1.8f,"Orb has limited damage and lifetime");TimeAt(23);Call("CastJourneyOrb");Check(List("shots").Count==1&&F(p,"energy")==80,"At most one orb exists even after cooldown");Set(shot,"target",null);Call("UpdateShot",0,.01f);Check(!(bool)Get(shot,"tracking"),"An orb without its target does not acquire another");Set(p,"clearedCombatRooms",6);Call("CheckPendingLesson");Call("LearnPendingLesson");Quiet();Check((bool)Get(p,"bladeLearned"),"Six combat rooms unlock learning wind blade");Set(p,"clearedCombatRooms",10);Call("CheckPendingLesson");Call("LearnPendingLesson");Quiet();Check((bool)Get(p,"waveLearned"),"Ten combat rooms unlock learning wind wave");List("shots").Clear();TimeAt(30);Set(p,"energy",100f);Call("CastWindBlade");Check(List("shots").Count==1&&I(List("shots")[0],"hitsLeft")==2&&F(p,"energy")==80,"Wind blade is straight, costs twenty and pierces two enemies");Check(Mathf.Abs((float)typeof(NakiPrototype).GetMethod("ElementMultiplier",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new[]{EnumValue("Element","Wind"),EnumValue("Element","Lightning")})-1.3f)<.001f,"Wind deals thirty percent more damage to lightning");
List("shots").Clear();Call("SpawnShot",new Vector2(.2f,-2),Vector2.zero,true,null,(Vector2?)new Vector2(.2f,-2));Call("SpawnShot",new Vector2(.3f,-2),Vector2.zero,true,null,(Vector2?)new Vector2(.3f,-2));Set(List("shots")[1],"dispellable",false);Call("CastWindWave");Check(List("shots").Count==1&&!(bool)Get(List("shots")[0],"dispellable")&&F(p,"energy")==50,"Wind wave removes ordinary projectiles and preserves protected hazards");Set(p,"shield",4f);Set(p,"invulnerableUntil",0f);Call("TakeJourneyDamage",2f,EnumValue("Element","Lightning"));Check(Mathf.Abs(F(p,"shield")-2.6f)<.001f,"Wind guard reduces lightning damage by thirty percent");
var ends=(int[])Get(p,"stageEnds");Enter(ends[2]);object boss=List("enemies")[0];Set(boss,"affinity",EnumValue("Element","Lightning"));Set(boss,"windup",1f);Set(boss,"hp",1000f);TimeAt(40);for(int i=0;i<3;i++)Call("ApplyElementDamage",boss,1f,EnumValue("Element","Wind"));Check(F(boss,"windup")==0&&F(boss,"poiseReadyAt")==46,"Three wind hits interrupt lightning boss and start protection");Set(boss,"windup",1f);for(int i=0;i<3;i++)Call("ApplyElementDamage",boss,1f,EnumValue("Element","Wind"));Check(F(boss,"windup")==1,"Poise protection prevents repeated interrupts");}
static void Equipment(){Check(((Array)Get(p,"weaponCatalog")).Length==8,"Eight curated weapon definitions load");foreach(object def in (Array)Get(p,"weaponCatalog"))Check(Get(def,"sprite")!=null,"Weapon sprite available: "+Get(def,"name"));int[] carried=(int[])Get(p,"carriedWeapons");Check(carried[0]==0&&carried[1]==-1,"Fresh run starts with one sword and one empty slot");object node=List("journeyRooms")[0];Type t=typeof(NakiPrototype).GetNestedType("StoredWeapon",BindingFlags.NonPublic);object stored=Activator.CreateInstance(t,true);Set(stored,"id",3);Set(stored,"at",(Vector2)Get(p,"position"));((IList)Get(node,"drops")).Add(stored);Call("CreateWeaponDropVisual",stored);Call("PickUpWeapon",List("worldWeapons")[0]);Check(carried[1]==3&&I(p,"equippedSlot")==1,"Picking up staff fills second slot and equips it");Call("SwitchWeapon");Check(I(p,"equippedSlot")==0,"H action switches to first weapon");Call("SwitchWeapon");TimeAt(20);Set(p,"position",new Vector2(0,-2));Set(p,"facing",Vector2.right);Set(p,"energy",100f);Call("UseEquippedWeapon");Check(List("shots").Count==1&&F(p,"energy")==95&&Get(List("shots")[0],"element").ToString()=="Light","Staff shoots its own typed mana projectile");Call("UpdatePixelHero",Vector2.zero);Capture("staff-body");Set(p,"equippedSlot",0);Set(p,"clock",21f);Call("UpdatePixelHero",Vector2.right);Capture("sword-body");
Set(stored,"id",2);((IList)Get(node,"drops")).Add(stored);Call("CreateWeaponDropVisual",stored);Call("PickUpWeapon",List("worldWeapons")[0]);Check(((IList)Get(node,"drops")).Count==1,"Replacing one of two weapons leaves previous weapon on floor");int dropId=I(((IList)Get(node,"drops"))[0],"id");Enter(1);Enter(0);Check(List("worldWeapons").Count==1&&I(Get(List("worldWeapons")[0],"data"),"id")==dropId,"Dropped weapon persists across room revisits");}
static void Progression(){bool counts=true;for(int id=0;id<39;id++){object n=List("journeyRooms")[id];if(Get(n,"kind").ToString()!="Combat")continue;Enter(id);int stage=I(n,"stage");counts&=List("pendingSpawns").Count>=4+stage&&I(n,"waves")>=2;TimeAt(F(p,"clock")+1);Call("TickPendingSpawns");counts&=List("pendingSpawns").Count==0&&List("enemies").Count>=4+stage;}Check(counts,"Three floors increase enemy counts and retain multi-wave combat");Fresh();int combat=-1;for(int id=0;id<39;id++)if(Get(List("journeyRooms")[id],"kind").ToString()=="Combat"){combat=id;break;}Enter(combat);Set(p,"energy",31f);Call("ClearJourneyRoom");Check(I(p,"clearedCombatRooms")==1&&F(p,"energy")==31,"Combat clear advances learning without refilling mana");Call("ClearJourneyRoom");Check(I(p,"clearedCombatRooms")==1,"Clearing a room twice cannot farm learning count");}
static void Bosses(){for(int variant=0;variant<3;variant++){p.bossPracticeMode=true;p.bossOverride=variant;p.lightningTrialMode=variant==1;Call("BeginJourney",false);Quiet();object boss=List("enemies")[0];Check(Get(boss,"kind").ToString()==new[]{"WindScorpion","Colossus","ApeKing"}[variant],"Practice selects boss candidate "+variant);if(variant==1)Check(Get(boss,"affinity").ToString()=="Lightning"&&Get(boss,"attackElement").ToString()=="Lightning","Trial boss uses lightning affinity and attacks");for(int i=0;i<3;i++){TimeAt(30+i*3);Set(p,"health",6f);Set(boss,"attackNumber",i);Call("BeginJourneyAttack",boss);Call("UpdateJourneyEnemy",boss,1f);}Check(I(boss,"attackNumber")==3,"Boss resolves all three attack patterns "+variant);Call("UpdatePixelHero",Vector2.zero);Capture("boss-"+variant);Call("DamageEnemy",boss,100000f);Call("TickJourney",.01f);Check((bool)Get(p,"journeyComplete")&&(bool)Get(p,"windEmpowered"),"Final boss awards wind fragment "+variant);Call("AdvanceJourneyStory",false);Call("AdvanceJourneyStory",false);Check((bool)Get(p,"showRainCG"),"Rain CG follows natural restoration dialogue "+variant);}p.bossPracticeMode=false;p.lightningTrialMode=false;p.bossOverride=-1;Fresh();int[] ends=(int[])Get(p,"stageEnds");for(int stage=0;stage<2;stage++){Enter(ends[stage]);object g=List("enemies")[0];Call("DamageEnemy",g,100000f);Call("TickJourney",.01f);Check(Get(p,"stairs")!=null&&!(bool)Get(p,"journeyComplete"),"Guardian opens next-floor stair without ending island "+stage);Quiet();}}
static void Restarts(){Fresh();string a=Signature();int seed=I(p,"activeSeed");Set(p,"shield",0f);Set(p,"orbLearned",true);p.swordDamage+=20;Call("ResetRoom");Check(I(p,"activeSeed")==seed&&Signature()==a&&F(p,"shield")==4&&!(bool)Get(p,"orbLearned")&&p.swordDamage==18,"Retry preserves route and resets run progression");Call("BeginJourney",true);Check(I(p,"activeSeed")!=seed,"New journey creates a different seed");}
static void Capture(string name){Camera c=(Camera)Get(p,"view");var old=c.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(1600,900,24);var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);try{c.aspect=1600f/900;c.orthographicSize=5.5f;c.transform.position=new Vector3(0,0,-10);c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(Output+name+".png",tex.EncodeToPNG());}finally{c.targetTexture=old;RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
